-- Fillers once the upgrades run out (ticket 47): new Balance Config group shared.overflow — Limit Break bonuses
-- (damage / max HP / speed / crit per pick, max picks each), training a Bench entry, a Gold bag and Recover, with
-- their offer weights. Patched into the live config_schema so publish_config accepts them; published versions
-- without the group use these defaults.
update public.config_schema set schema = jsonb_set(schema,
  '{properties,shared,properties,overflow}',
  $j${"description":"Fillers when too few upgrades are left (level-up / chest)","default":{},"type":"object","properties":{"dmg":{"default":0.04,"description":"Limit Break: damage + per pick","type":"number","minimum":0,"maximum":1},"hp":{"default":0.05,"description":"Limit Break: max HP + (share) per pick","type":"number","minimum":0,"maximum":1},"spd":{"default":0.03,"description":"Limit Break: move speed + per pick","type":"number","minimum":0,"maximum":1},"crit":{"default":0.02,"description":"Limit Break: crit chance + per pick (the crit cap still applies)","type":"number","minimum":0,"maximum":1},"max":{"default":10,"description":"Limit Break: picks of each bonus per Run","type":"number","minimum":0,"maximum":50},"gold":{"default":25,"description":"Gold bag: Gold × Chapter","type":"number","minimum":0,"maximum":250},"wLb":{"default":1,"description":"Weight: each Limit Break bonus","type":"number","minimum":0,"maximum":10},"wTrain":{"default":1,"description":"Weight: train one Bench entry (+1 level), per entry","type":"number","minimum":0,"maximum":10},"wGold":{"default":0.8,"description":"Weight: Gold bag","type":"number","minimum":0,"maximum":10},"wHeal":{"default":0.8,"description":"Weight: Recover (only offered when HP is not full)","type":"number","minimum":0,"maximum":10}}}$j$::jsonb)
where id = 1;
